const { VoltAgent, createTool } = require('@voltagent/core');
const { XSAIProvider } = require('@voltagent/xsai');
const { z } = require('zod');
const fs = require('fs');
const path = require('path');

const logFile = '/home/user/app/hooks.log';

const calculate_sum = createTool({
  name: 'calculate_sum',
  description: 'Calculate the sum of two numbers',
  parameters: z.object({
    a: z.number(),
    b: z.number(),
  }),
  execute: async ({ a, b }) => {
    return a + b;
  },
});

const provider = new XSAIProvider({
  apiKey: process.env.OPENAI_API_KEY,
});

const agent = new VoltAgent({
  name: 'SumAgent',
  instructions: 'You calculate sums.',
  model: {
    provider,
    model: 'gpt-4o-mini',
  },
  tools: [calculate_sum],
  hooks: {
    onStart: async () => {
      fs.appendFileSync(logFile, 'HOOK: onStart\n');
    },
    onToolStart: async ({ toolName }) => {
      if (toolName === 'calculate_sum') {
        fs.appendFileSync(logFile, 'HOOK: onToolStart - calculate_sum\n');
      }
    },
    onToolEnd: async ({ toolName }) => {
      if (toolName === 'calculate_sum') {
        fs.appendFileSync(logFile, 'HOOK: onToolEnd - calculate_sum\n');
      }
    },
    onEnd: async () => {
      fs.appendFileSync(logFile, 'HOOK: onEnd\n');
    },
  },
});

async function main() {
  try {
    const result = await agent.generateText({
      prompt: 'Calculate the sum of 15 and 27',
    });
    console.log('Agent Result:', result.text);
  } catch (error) {
    console.error('Error:', error);
  }
}

main();

