/home/user/app/node_modules/@voltagent/xsai/dist/index.mjs.map:{"version":3,"sources":["../src/index.ts","../src/utils.ts"],"sourcesContent":["import type {
  GenerateObjectOptions as BaseGenerateObjectOptions,
  BaseMessage,
  StreamObjectOptions as BaseStreamObjectOptions,
  StreamTextOptions as BaseStreamTextOptions,
  BaseTool,
  GenerateTextOptions,
  LLMProvider,
