/home/user/app/node_modules/@voltagent/xsai/dist/index.mjs.map:{"version":3,"sources":["../src/index.ts","../src/utils.ts"],"sourcesContent":["import type {
  GenerateObjectOptions as BaseGenerateObjectOptions,
  BaseMessage,
  StreamObjectOptions as BaseStreamObjectOptions,
  StreamTextOptions as BaseStreamTextOptions,
  BaseTool,
  GenerateTextOptions,
  LLMProvider,
  MessageRole,
  ProviderObjectResponse,
  ProviderObjectStreamResponse,
  ProviderTextResponse,
  ProviderTextStreamResponse,
  StepWithContent,
} from "@voltagent/core";
import { createAsyncIterableStream } from "@voltagent/core";
import type { SetRequired } from "type-fest";
import type {
  FileContentPart,
  GenerateObjectResult,
  GenerateTextResult,
  ImageContentPart,
  Message,
  StreamObjectResult,
  StreamTextResult,
  TextContentPart,
  Tool,
} from "xsai";
import type { z } from "zod";
import { createMappedFullStream } from "./utils";

export class XSAIProvider implements LLMProvider<string> {
  private apiKey: string;
  private baseURL: string;

  /**
   * Creates a new XSAIProvider instance
   * @param options - Configuration options
   * @param options.apiKey - The API key for authentication
   * @param options.baseURL - The base URL for API requests. Defaults to "https://api.openai.com/v1/"
   */
  constructor(options: { apiKey: string; baseURL?: string }) {
    this.apiKey = options.apiKey;
    this.baseURL = options.baseURL || "https://api.openai.com/v1/";
    // Bind methods to preserve 'this' context
    this.generateText = this.generateText.bind(this);
    this.streamText = this.streamText.bind(this);
    this.generateObject = this.generateObject.bind(this);
    this.streamObject = this.streamObject.bind(this);
    this.toMessage = this.toMessage.bind(this);
    this.convertTools = this.convertTools.bind(this);
    this.createStepFinishHandler = this.createStepFinishHandler.bind(this);
    this.getModelIdentifier = this.getModelIdentifier.bind(this);
  }

  getModelIdentifier = (model: string): string => {
    // The model itself is the string identifier for XsAIProvider
    return model;
  };

  toMessage = (message: BaseMessage): Message => {
    if (typeof message.content === "string") return message as Message;
    if (Array.isArray(message.content)) {
      const content: (FileContentPart | ImageContentPart | TextContentPart)[] = [];

      for (const part of message.content) {
        if (part.type === "text") {
          content.push(part as TextContentPart);
        } else if (part.type === "image") {
          if (typeof part.image === "string" || part.image instanceof URL) {
            content.push({
              type: "image_url",
              image_url: { url: part.image.toString() },
            } satisfies ImageContentPart);
          } else {
            console.warn(
              `[XSAIProvider] Message (role: ${message.role}) contained unsupported image part format...`,
            );
          }
        } else if (part.type === "file") {
          if (typeof part.data === "string" || part.data instanceof URL) {
            content.push({
              type: "file",
              file: {
                filename: part.filename,
                file_data: part.data.toString(),
              },
            } satisfies FileContentPart);
          } else {
            console.warn(
              `[XSAIProvider] Message (role: ${message.role}) contained unsupported file part format...`,
            );
          }
        } else {
          console.warn(
            `[XSAIProvider] Message (role: ${message.role}) contained unsupported content parts...`,
          );
        }
      }

      return { role: message.role, content } as Message;
    }
    // Handle unexpected content types (null, undefined, etc.)
    console.warn(
      `[XSAIProvider] Unknown or unsupported content type for message (role: ${message.role}):`,
      message.content,
    );

    return { role: message.role, content: "" } as Message; // Fallback to empty string
  };

  convertTools = async (tools: BaseTool[]): Promise<Tool[] | undefined> => {
    if (!tools || tools.length === 0) {
      return undefined;
    }

    const { tool } = await import("xsai");

    const functions = await Promise.all(
      tools.map(async (t) => {
        return await tool({
          name: t.name,
          description: t.description,
          parameters: t.parameters as any,
          execute: async (input) => {
            return await t.execute(input);
          },
        });
      }),
    );

    return functions;
  };

  createStepFinishHandler = (onStepFinish?: (step: StepWithContent) => void | Promise<void>) => {
    if (!onStepFinish) return undefined;
    // TODO: Handle GenerateTextResult and StreamTextResult
    return async (result: any) => {
      // Handle text response
      if ("text" in result && result.text) {
        const step = {
          id: "",
          type: "text" as const,
          content: result.text,
          role: "assistant" as MessageRole,
          usage: {
            promptTokens: result.usage.prompt_tokens,
            completionTokens: result.usage.completion_tokens,
            totalTokens: result.usage.total_tokens,
          },
        };
        await onStepFinish(step);
      } else if ("choices" in result && result.choices?.[0]?.message?.content) {
        const step = {
          id: "",
          type: "text" as const,
          content: result.choices[0].message.content,
          role: "assistant" as MessageRole,
          usage: result.usage
            ? {
                promptTokens: result.usage.prompt_tokens,
                completionTokens: result.usage.completion_tokens,
                totalTokens: result.usage.total_tokens,
              }
            : undefined,
        };
        await onStepFinish(step);
      }

      // Handle tool calls
      if (result.toolCalls && result.toolCalls.length > 0) {
        for (const toolCall of result.toolCalls) {
          const step: StepWithContent = {
            id: toolCall.toolCallId,
            type: "tool_call" as const,
            name: toolCall.toolName,
            arguments: toolCall.args as any,
            content: JSON.stringify([
              {
                type: "tool-call",
                toolCallId: toolCall.toolCallId,
                toolName: toolCall.toolName,
                args: toolCall.args,
              },
            ]),
            role: "assistant" as MessageRole,
            usage: result.usage
              ? {
                  promptTokens: result.usage.prompt_tokens,
                  completionTokens: result.usage.completion_tokens,
                  totalTokens: result.usage.total_tokens,
                }
              : undefined,
          };
          await onStepFinish(step);
        }
      }

      // Handle tool results
      if (result.toolResults && result.toolResults.length > 0) {
        for (const toolResult of result.toolResults) {
          const step = {
            id: toolResult.toolCallId,
            type: "tool_result" as const,
            name: toolResult.toolName,
            result: toolResult.result,
            content: JSON.stringify([
              {
                type: "tool-result",
                toolCallId: toolResult.toolCallId,
                toolName: toolResult.toolName,
                result: toolResult.result,
              },
            ]),
            role: "assistant" as MessageRole,
            usage: result.usage
              ? {
                  promptTokens: result.usage.prompt_tokens,
                  completionTokens: result.usage.completion_tokens,
                  totalTokens: result.usage.total_tokens,
                }
              : undefined,
          };
          await onStepFinish(step);
        }
      }
    };
  };

  generateText = async (
    options: GenerateTextOptions<string>,
  ): Promise<ProviderTextResponse<GenerateTextResult>> => {
    const { generateText } = await import("xsai");
    const xsaiMessages = options.messages.map(this.toMessage);
    const xsaiTools = options.tools ? await this.convertTools(options.tools) : undefined;

    const result = await generateText({
      apiKey: this.apiKey,
      messages: xsaiMessages,
      model: options.model,
      tools: xsaiTools,
      maxSteps: xsaiTools ? options.maxSteps : undefined,
      baseURL: this.baseURL,
      signal: options.signal,
      ...options.provider,
      onStepFinish: this.createStepFinishHandler(options.onStepFinish),
    });

    // Return standardized response
    return {
      provider: result,
      text: result.text || "", // Ensure text is always a string
      usage: result.usage
        ? {
            promptTokens: result.usage.prompt_tokens,
            completionTokens: result.usage.completion_tokens,
            totalTokens: result.usage.total_tokens,
          }
        : undefined,
      toolCalls: result.toolCalls,
      toolResults: result.toolResults,
      finishReason: result.finishReason,
    };
  };

  async streamText(
    options: BaseStreamTextOptions<string>,
  ): Promise<SetRequired<ProviderTextStreamResponse<StreamTextResult>, "fullStream">> {
    const { streamText } = await import("xsai");
    const xsaiMessages = options.messages.map(this.toMessage);
    const xsaiTools = options.tools ? await this.convertTools(options.tools) : undefined;

    const result = await streamText({
      apiKey: this.apiKey,
      messages: xsaiMessages,
      model: options.model,
      tools: xsaiTools,
      maxSteps: xsaiTools ? options.maxSteps : undefined,
      baseURL: this.baseURL,
      signal: options.signal,
      streamOptions: {
        includeUsage: false,
      },
      ...options.provider,
      onStepFinish: this.createStepFinishHandler(options.onStepFinish),
      ...(options.onFinish
        ? {
            onFinish: async (result) =>
              await options.onFinish?.({
                text: result?.text || "",
                usage: result?.usage
                  ? {
                      promptTokens: result.usage.prompt_tokens,
                      completionTokens: result.usage.completion_tokens,
                      totalTokens: result.usage.total_tokens,
                    }
                  : undefined,
                finishReason: result?.finishReason,
                providerResponse: result,
              }),
          }
        : {}),
    });

    // Return only provider and textStream - usage, toolCalls, etc. come in the stream
    return {
      provider: result,
      textStream: createAsyncIterableStream(result.textStream),
      fullStream: createMappedFullStream(createAsyncIterableStream(result.fullStream)),
    };
  }

  generateObject = async <TSchema extends z.ZodType>(
    options: BaseGenerateObjectOptions<string, TSchema>,
  ): Promise<ProviderObjectResponse<GenerateObjectResult<z.infer<TSchema>>, z.infer<TSchema>>> => {
    const { generateObject } = await import("xsai");
    const xsaiMessages = options.messages.map(this.toMessage);

    const onStepFinishWrapper = options.onStepFinish
      ? // TODO: fix type
        async (result: any) => {
          // For generateObject, we need to wrap text content in a special format
          const handler = this.createStepFinishHandler(async (step) => {
            if (step.type === "text") {
              // Override the content format for text steps in generateObject
              const textStep = {
                ...step,
                content: JSON.stringify([
                  {
                    type: "text",
                    text: step.content,
                  },
                ]),
              };
              await options.onStepFinish?.(textStep);
            } else {
              await options.onStepFinish?.(step);
            }
          });

          if (handler) {
            handler(result);
          }
        }
      : undefined;

    const result = await generateObject({
      apiKey: this.apiKey,
      messages: xsaiMessages,
      model: options.model,
      schema: options.schema,
      baseURL: this.baseURL,
      signal: options.signal,
      ...options.provider,
      onStepFinish: onStepFinishWrapper,
    });

    // Return standardized response
    return {
      provider: result,
      object: result.object,
      usage: result.usage
        ? {
            promptTokens: result.usage.prompt_tokens,
            completionTokens: result.usage.completion_tokens,
            totalTokens: result.usage.total_tokens,
          }
        : undefined,
      finishReason: result.finishReason,
    };
  };

  async streamObject<TSchema extends z.ZodType>(
    options: BaseStreamObjectOptions<string, TSchema>,
  ): Promise<ProviderObjectStreamResponse<StreamObjectResult<z.infer<TSchema>>, z.infer<TSchema>>> {
    const { streamObject } = await import("xsai");
    const xsaiMessages = options.messages.map(this.toMessage);

    const onStepFinishWrapper = options.onStepFinish
      ? async (result: any) => {
          // For streamObject, we need to wrap text content in a special format
          const handler = this.createStepFinishHandler(async (step) => {
            if (step.type === "text") {
              // Override the content format for text steps in streamObject
              const textStep = {
                ...step,
                content: JSON.stringify(step.content),
              };
              await options.onStepFinish?.(textStep);
            } else {
              await options.onStepFinish?.(step);
            }
          });

          if (handler) {
            await handler(result);
          }

          if (options.onFinish) {
            await options.onFinish({
              object: result.choices?.[0]?.message?.content,
            });
          }
        }
      : undefined;

    const result = await streamObject({
      apiKey: this.apiKey,
      messages: xsaiMessages,
      model: options.model,
      schema: options.schema,
      baseURL: this.baseURL,
      signal: options.signal,
      ...options.provider,
      onStepFinish: onStepFinishWrapper,
    });

    // Create a ReadableStream for object chunks

    // Return only provider and objectStream - other data comes in the stream
    return {
      provider: result,
      objectStream: createAsyncIterableStream(result.partialObjectStream),
    };
  }
}
","import type { StreamPart } from "@voltagent/core";
import { P, match } from "ts-pattern";
import type { StreamTextEvent } from "xsai";

/**
 * Map xsAI StreamTextEvent to our standard StreamPart
 * @param part - The part to map
 * @returns The mapped part or null if the part is not supported
 */
export function mapToStreamPart(part: StreamTextEvent): StreamPart | null {
  return (
    match(part)
      .returnType<StreamPart | null>()
      .with({ type: "text-delta" }, (p) => ({
        type: "text-delta",
        textDelta: p.text,
      }))
      .with({ type: "reasoning-delta" }, (p) => ({
        type: "reasoning",
        reasoning: p.text,
      }))
      // TODO: source
      .with({ type: "tool-call" }, (p) => ({
        type: "tool-call",
        toolCallId: p.toolCallId,
        toolName: p.toolName,
        args: JSON.parse(p.args),
      }))
      .with({ type: "tool-result" }, (p) => ({
        type: "tool-result",
        toolCallId: p.toolCallId,
        toolName: p.toolName,
        result: p.result,
      }))
      .with({ type: "finish" }, (p) => ({
        type: "finish",
        finishReason: p.finishReason,
        usage: match(p)
          .with(
            {
              usage: {
                prompt_tokens: P.number,
                completion_tokens: P.number,
                total_tokens: P.number,
              },
            },
            (p) => ({
              promptTokens: p.usage.prompt_tokens,
              completionTokens: p.usage.completion_tokens,
              totalTokens: p.usage.total_tokens,
            }),
          )
          .otherwise(() => undefined),
      }))
      .with({ type: "error" }, (p) => ({
        type: "error",
        error: p.error as Error,
      }))
      .otherwise(() => null)
  );
}

/**
 * Create mapped fullStream that converts xsAI parts to our standard parts
 * @param originalStream - The original stream of parts from the xsAI SDK
 * @returns A new stream of parts that are converted to our standard parts
 */
export function createMappedFullStream(
  originalStream: AsyncIterable<StreamTextEvent>,
): AsyncIterable<StreamPart> {
  return {
    async *[Symbol.asyncIterator]() {
      for await (const part of originalStream) {
        const mappedPart = mapToStreamPart(part);
        if (mappedPart !== null) {
          yield mappedPart;
        }
      }
    },
